<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/report_error.php';
try{$uid=(int)requireAuth()->id;$year=(int)($_GET['year']??date('Y'));if($year<2000||$year>2200)throw new InvalidArgumentException('Invalid year');$conn=db();requirePermission($conn,$uid,'reports.view');$s=$conn->prepare('SELECT id,schedule_type,reference,description,event_date,beneficiary,gross_amount,opening_book_value,annual_rate,accounting_amount,fiscal_amount,fiscal_addition,fiscal_deduction,closing_book_value,timing,legal_basis,evidence_reference,notes,status,created_at FROM erp_tax_schedule_entries WHERE user_id=? AND fiscal_year=? ORDER BY schedule_type,event_date,reference');$s->bind_param('ii',$uid,$year);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();jsonResponse(['success'=>true,'year'=>$year,'data'=>$rows,'filing_ready'=>false]);}catch(Throwable $e){reportFailureResponse($e,'Could not load the tax schedules.','TAX_SCHEDULE_LOAD_FAILED');}
